async function seed() {
  const snap = await db.collection('universities').get();
  const existing = new Set();
  snap.forEach(doc => existing.add(doc.data().name));
  console.log('Existing:', existing.size);
  let added = 0, skipped = 0;
  for (const uni of universities) {
    if (existing.has(uni.name)) { skipped++; continue; }
    uni.logo = 'https://www.google.com/s2/favicons?domain=' + uni.website + '&sz=128';
    await db.collection('universities').add({...uni, createdAt: new Date()});
    added++;
    if (added % 20 === 0) console.log('✅ ' + added + ' added so far...');
  }
  console.log('\n🎉 Done! Added: ' + added + ', Skipped: ' + skipped);
  process.exit(0);
}
seed().catch(e => { console.error('❌', e.message); process.exit(1); });
